\begin{tabular}{lrrr}
\toprule
Type & Amb.\ (mean $\pm$ SD) & Unamb.\ (mean $\pm$ SD) & $\Delta$ \\
\midrule
auth\_scope & $19.0 \pm 3.3$ & $55.0 \pm 8.1$ & $+36.1$ \\
incompleteness & $12.2 \pm 2.4$ & $46.8 \pm 9.1$ & $+34.6$ \\
lexical & $11.4 \pm 2.3$ & $37.0 \pm 5.8$ & $+25.7$ \\
